import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
    proxy: {
      '/api': 'http://localhost:34517',
    },
  },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
  },
});

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './index.css';

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-color: #f9fafb;
  color: #111827;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

h1 {
  font-size: 1.875rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.card {
  background: white;
  border-radius: 0.5rem;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}

.filters {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: 0.375rem;
  border: 1px solid #d1d5db;
  background-color: white;
  color: #374151;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
}

button:hover:not(:disabled) {
  background-color: #f3f4f6;
  border-color: #9ca3af;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

button.active-filter {
  background-color: #2563eb;
  color: white;
  border-color: #2563eb;
}

button.active-filter:hover {
  background-color: #1d4ed8;
}

.actions-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.left-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.selection-info {
  font-size: 0.875rem;
  color: #4b5563;
}

.btn-archive {
  background-color: #dc2626;
  color: white;
  border-color: #dc2626;
}

.btn-archive:hover:not(:disabled) {
  background-color: #b91c1c;
}

.btn-secondary {
  background-color: #f3f4f6;
  color: #374151;
  border-color: #d1d5db;
}

.grid-container {
  overflow-x: auto;
  border: 1px solid #e5e7eb;
  border-radius: 0.375rem;
  background: white;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

th, td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #e5e7eb;
}

th {
  background-color: #f9fafb;
  font-weight: 600;
  color: #374151;
  font-size: 0.875rem;
}

tr:hover {
  background-color: #f9fafb;
}

.pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1rem;
}

.pagination-info {
  font-size: 0.875rem;
  color: #4b5563;
}

.empty-state {
  padding: 3rem 1rem;
  text-align: center;
  color: #6b7280;
  font-size: 1rem;
}

import React, { useState, useMemo } from 'react';
import {
  QueryClient,
  QueryClientProvider,
  useQuery,
  useMutation,
  useQueryClient,
} from '@tanstack/react-query';
import {
  useReactTable,
  getCoreRowModel,
  flexRender,
  ColumnDef,
} from '@tanstack/react-table';

// Initialize Query Client
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      retry: false,
    },
  },
});

interface Item {
  id: number;
  name: string;
  category: string;
  status: 'active' | 'archived';
}

interface ItemsResponse {
  rows: Item[];
  total: number;
  page: number;
  pageSize: number;
}

function AdminConsole() {
  const [statusFilter, setStatusFilter] = useState<'active' | 'archived'>('active');
  const [page, setPage] = useState(1);
  const pageSize = 10;

  // Selection states
  const [isAllSelected, setIsAllSelected] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());
  const [excludedIds, setExcludedIds] = useState<Set<number>>(new Set());

  const queryClientInstance = useQueryClient();

  // Fetch items
  const { data, isLoading } = useQuery<ItemsResponse>({
    queryKey: ['items', statusFilter, page, pageSize],
    queryFn: async () => {
      const res = await fetch(
        `/api/items?status=${statusFilter}&page=${page}&pageSize=${pageSize}`
      );
      if (!res.ok) throw new Error('Network response was not ok');
      return res.json();
    },
  });

  const items = data?.rows ?? [];
  const totalCount = data?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));

  // Extract IDs of items on the current page
  const currentPageIds = useMemo(() => items.map((item) => item.id), [items]);

  // Selection helpers
  const isRowSelected = useMemo(() => {
    return (id: number) => {
      if (isAllSelected) {
        return !excludedIds.has(id);
      }
      return selectedIds.has(id);
    };
  }, [isAllSelected, excludedIds, selectedIds]);

  const toggleRow = (id: number) => {
    if (isAllSelected) {
      setExcludedIds((prev) => {
        const next = new Set(prev);
        if (next.has(id)) {
          next.delete(id);
        } else {
          next.add(id);
        }
        return next;
      });
    } else {
      setSelectedIds((prev) => {
        const next = new Set(prev);
        if (next.has(id)) {
          next.delete(id);
        } else {
          next.add(id);
        }
        return next;
      });
    }
  };

  const areAllOnPageSelected = useMemo(() => {
    return currentPageIds.length > 0 && currentPageIds.every((id) => isRowSelected(id));
  }, [currentPageIds, isRowSelected]);

  const togglePageSelection = () => {
    if (areAllOnPageSelected) {
      // Deselect all on current page
      if (isAllSelected) {
        setExcludedIds((prev) => {
          const next = new Set(prev);
          currentPageIds.forEach((id) => next.add(id));
          return next;
        });
      } else {
        setSelectedIds((prev) => {
          const next = new Set(prev);
          currentPageIds.forEach((id) => next.delete(id));
          return next;
        });
      }
    } else {
      // Select all on current page
      if (isAllSelected) {
        setExcludedIds((prev) => {
          const next = new Set(prev);
          currentPageIds.forEach((id) => next.delete(id));
          return next;
        });
      } else {
        setSelectedIds((prev) => {
          const next = new Set(prev);
          currentPageIds.forEach((id) => next.add(id));
          return next;
        });
      }
    }
  };

  const selectionCount = useMemo(() => {
    if (isAllSelected) {
      return Math.max(0, totalCount - excludedIds.size);
    }
    return selectedIds.size;
  }, [isAllSelected, totalCount, excludedIds, selectedIds]);

  const clearSelection = () => {
    setIsAllSelected(false);
    setSelectedIds(new Set());
    setExcludedIds(new Set());
  };

  const selectAllMatching = () => {
    setIsAllSelected(true);
    setExcludedIds(new Set());
    setSelectedIds(new Set());
  };

  const handleFilterChange = (newStatus: 'active' | 'archived') => {
    setStatusFilter(newStatus);
    setPage(1);
    clearSelection();
  };

  // Bulk Archive Mutation
  const archiveMutation = useMutation({
    mutationFn: async (payload: any) => {
      const res = await fetch('/api/items/bulk-archive', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });
      if (!res.ok) throw new Error('Failed to archive items');
      return res.json();
    },
    onMutate: async (payload) => {
      // Cancel outgoing refetches
      await queryClientInstance.cancelQueries({ queryKey: ['items'] });

      // Snapshot previous items for rollback
      const previousItems = queryClientInstance.getQueryData([
        'items',
        statusFilter,
        page,
        pageSize,
      ]);

      // Snapshot selection state
      const prevSelection = { isAllSelected, selectedIds, excludedIds };

      // Optimistically clear selection
      setIsAllSelected(false);
      setSelectedIds(new Set());
      setExcludedIds(new Set());

      // Optimistically update cache
      queryClientInstance.setQueryData(
        ['items', statusFilter, page, pageSize],
        (old: any) => {
          if (!old) return old;

          if (payload.mode === 'all') {
            return {
              ...old,
              rows: [],
              total: 0,
            };
          }

          // mode: 'selected'
          const archivedIdsSet = new Set(payload.ids);
          const nextRows = old.rows.filter((row: any) => !archivedIdsSet.has(row.id));
          const removedCount = old.rows.length - nextRows.length;
          return {
            ...old,
            rows: nextRows,
            total: Math.max(0, old.total - removedCount),
          };
        }
      );

      return { previousItems, prevSelection };
    },
    onError: (err, payload, context: any) => {
      if (context?.previousItems) {
        queryClientInstance.setQueryData(
          ['items', statusFilter, page, pageSize],
          context.previousItems
        );
      }
      if (context?.prevSelection) {
        setIsAllSelected(context.prevSelection.isAllSelected);
        setSelectedIds(context.prevSelection.selectedIds);
        setExcludedIds(context.prevSelection.excludedIds);
      }
    },
    onSettled: () => {
      queryClientInstance.invalidateQueries({ queryKey: ['items'] });
    },
  });

  const handleBulkArchive = async () => {
    if (selectionCount === 0) return;

    let payload: any;
    if (isAllSelected && excludedIds.size === 0) {
      payload = { mode: 'all', status: statusFilter };
    } else if (isAllSelected) {
      // Fetch all matching IDs to filter out excluded ones
      try {
        const res = await fetch(`/api/items?status=${statusFilter}&page=1&pageSize=1000`);
        if (!res.ok) throw new Error('Failed to fetch matching items');
        const data: ItemsResponse = await res.json();
        const allIds = data.rows.map((r) => r.id);
        const ids = allIds.filter((id) => !excludedIds.has(id));
        payload = { mode: 'selected', ids };
      } catch (error) {
        console.error(error);
        return;
      }
    } else {
      payload = { mode: 'selected', ids: Array.from(selectedIds) };
    }

    archiveMutation.mutate(payload);
  };

  // Define columns for TanStack Table
  const columns = useMemo<ColumnDef<Item>[]>(
    () => [
      {
        id: 'select',
        header: () => (
          <input
            type="checkbox"
            data-testid="select-page-checkbox"
            checked={areAllOnPageSelected}
            onChange={togglePageSelection}
            style={{ cursor: 'pointer' }}
          />
        ),
        cell: ({ row }) => (
          <input
            type="checkbox"
            data-testid={`row-checkbox-${row.original.id}`}
            checked={isRowSelected(row.original.id)}
            onChange={() => toggleRow(row.original.id)}
            style={{ cursor: 'pointer' }}
          />
        ),
      },
      {
        accessorKey: 'id',
        header: 'ID',
      },
      {
        accessorKey: 'name',
        header: 'Name',
      },
      {
        accessorKey: 'category',
        header: 'Category',
      },
      {
        accessorKey: 'status',
        header: 'Status',
        cell: ({ row }) => (
          <span
            style={{
              padding: '0.25rem 0.5rem',
              borderRadius: '0.25rem',
              fontSize: '0.75rem',
              fontWeight: 600,
              backgroundColor: row.original.status === 'active' ? '#dcfce7' : '#f3f4f6',
              color: row.original.status === 'active' ? '#15803d' : '#4b5563',
              textTransform: 'capitalize',
            }}
          >
            {row.original.status}
          </span>
        ),
      },
    ],
    [areAllOnPageSelected, isRowSelected, toggleRow, togglePageSelection]
  );

  const table = useReactTable({
    data: items,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return (
    <div className="container">
      <h1>Items Admin Console</h1>

      <div className="card">
        {/* Status Filters */}
        <div className="filters">
          <button
            data-testid="filter-active"
            className={statusFilter === 'active' ? 'active-filter' : ''}
            onClick={() => handleFilterChange('active')}
          >
            Active
          </button>
          <button
            data-testid="filter-archived"
            className={statusFilter === 'archived' ? 'active-filter' : ''}
            onClick={() => handleFilterChange('archived')}
          >
            Archived
          </button>
        </div>

        {/* Action Bar */}
        <div className="actions-bar">
          <div className="left-actions">
            <span className="selection-info">
              Selected: <strong data-testid="selection-count">{selectionCount}</strong> of{' '}
              <strong data-testid="total-count">{totalCount}</strong> matching items
            </span>

            {areAllOnPageSelected && (
              <button
                data-testid="select-all-matching"
                onClick={selectAllMatching}
                disabled={isAllSelected && excludedIds.size === 0}
              >
                Select all {totalCount} matching items
              </button>
            )}

            {(selectionCount > 0) && (
              <button
                data-testid="clear-selection"
                className="btn-secondary"
                onClick={clearSelection}
              >
                Clear Selection
              </button>
            )}
          </div>

          <button
            data-testid="bulk-archive"
            className="btn-archive"
            onClick={handleBulkArchive}
            disabled={selectionCount === 0 || archiveMutation.isPending}
          >
            {archiveMutation.isPending ? 'Archiving...' : 'Archive Selected'}
          </button>
        </div>

        {/* Data Grid */}
        <div className="grid-container">
          {isLoading ? (
            <div style={{ padding: '2rem', textAlign: 'center' }}>Loading...</div>
          ) : items.length === 0 ? (
            <div data-testid="empty-state" className="empty-state">
              No rows found for this filter.
            </div>
          ) : (
            <table>
              <thead>
                {table.getHeaderGroups().map((headerGroup) => (
                  <tr key={headerGroup.id}>
                    {headerGroup.headers.map((header) => (
                      <th key={header.id}>
                        {header.isPlaceholder
                          ? null
                          : flexRender(header.column.columnDef.header, header.getContext())}
                      </th>
                    ))}
                  </tr>
                ))}
              </thead>
              <tbody>
                {table.getRowModel().rows.map((row) => (
                  <tr key={row.id} data-testid={`row-${row.original.id}`}>
                    {row.getVisibleCells().map((cell) => (
                      <td key={cell.id}>
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* Pagination Controls */}
        <div className="pagination">
          <button
            data-testid="prev-page"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page <= 1}
          >
            Previous
          </button>

          <span data-testid="page-indicator" className="pagination-info">
            Page {page} of {totalPages}
          </span>

          <button
            data-testid="next-page"
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages}
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <AdminConsole />
    </QueryClientProvider>
  );
}

import express from 'express';
import Database from 'better-sqlite3';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
app.use(express.json());

// Database setup
const dbPath = '/home/user/app/data/app.db';
const db = new Database(dbPath);

// Create table if it doesn't exist
db.exec(`
  CREATE TABLE IF NOT EXISTS items (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    status TEXT NOT NULL
  )
`);

// Idempotent seeding
const countResult = db.prepare('SELECT COUNT(*) as count FROM items').get();
if (countResult.count === 0) {
  const insertStmt = db.prepare('INSERT INTO items (id, name, category, status) VALUES (?, ?, ?, ?)');
  const insertMany = db.transaction(() => {
    for (let i = 1; i <= 57; i++) {
      const id = i;
      const name = `Item ${String(i).padStart(4, '0')}`;
      const category = ['Alpha', 'Bravo', 'Charlie'][(i - 1) % 3];
      const status = 'active';
      insertStmt.run(id, name, category, status);
    }
  });
  insertMany();
  console.log('Database seeded with 57 items.');
} else {
  console.log('Database already has items. Skipping seeding.');
}

// API Endpoints
// GET /api/items?status=<active|archived>&page=<n>&pageSize=<n>
app.get('/api/items', (req, res) => {
  try {
    const status = req.query.status || 'active';
    const page = parseInt(req.query.page, 10) || 1;
    const pageSize = parseInt(req.query.pageSize, 10) || 10;

    if (status !== 'active' && status !== 'archived') {
      return res.status(400).json({ error: 'Invalid status filter' });
    }

    const offset = (page - 1) * pageSize;

    // Get total matching
    const totalResult = db.prepare('SELECT COUNT(*) as count FROM items WHERE status = ?').get(status);
    const total = totalResult.count;

    // Get items for current page
    const rows = db.prepare('SELECT id, name, category, status FROM items WHERE status = ? LIMIT ? OFFSET ?').all(status, pageSize, offset);

    res.json({
      rows,
      total,
      page,
      pageSize
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// POST /api/items/bulk-archive
app.post('/api/items/bulk-archive', (req, res) => {
  try {
    const { mode } = req.body;

    if (mode === 'selected') {
      const { ids } = req.body;
      if (!Array.isArray(ids)) {
        return res.status(400).json({ error: 'Invalid ids array' });
      }
      if (ids.length === 0) {
        return res.json({ archived: 0 });
      }

      // Update their status to 'archived'
      const placeholders = ids.map(() => '?').join(',');
      const updateStmt = db.prepare(`UPDATE items SET status = 'archived' WHERE id IN (${placeholders})`);
      updateStmt.run(...ids);

      // Count how many of these IDs are now archived
      const countStmt = db.prepare(`SELECT COUNT(*) as count FROM items WHERE id IN (${placeholders}) AND status = 'archived'`);
      const countResult = countStmt.get(...ids);

      res.json({ archived: countResult.count });
    } else if (mode === 'all') {
      const { status } = req.body;
      if (status !== 'active' && status !== 'archived') {
        return res.status(400).json({ error: 'Invalid status' });
      }

      if (status === 'active') {
        // Find how many are active before archiving
        const beforeResult = db.prepare("SELECT COUNT(*) as count FROM items WHERE status = 'active'").get();
        const activeCount = beforeResult.count;

        // Archive them
        db.prepare("UPDATE items SET status = 'archived' WHERE status = 'active'").run();

        res.json({ archived: activeCount });
      } else {
        // Already archived
        const archivedResult = db.prepare("SELECT COUNT(*) as count FROM items WHERE status = 'archived'").get();
        res.json({ archived: archivedResult.count });
      }
    } else {
      res.status(400).json({ error: 'Invalid mode' });
    }
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Serve built frontend files
app.use(express.static(path.join(__dirname, 'dist')));

// Fallback to index.html for single-page app routing
app.get('*', (req, res, next) => {
  if (req.path.startsWith('/api')) {
    return next();
  }
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

const PORT = process.env.PORT || 34517;
app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

